local local_class = newclass("InfinityTowerRecordRoomController")

function local_class:init(cs_controller, scene)
	self.cs_controller = cs_controller
	if scene ~= nil then
		self.scene = scene()
	end

	-- 현재 층
	self.floor_id = CS.Oak.Tower1000Client.Instance.FloorId
end

function local_class:load_resource()
	local console_count = 0

	if game_string:IsThereString('tower_1000_' .. self.floor_id .. '_E') then
		console_count = 5
	elseif game_string:IsThereString('tower_1000_' .. self.floor_id .. '_D') then
		console_count = 4
	elseif game_string:IsThereString('tower_1000_' .. self.floor_id .. '_C') then
		console_count = 3
	elseif game_string:IsThereString('tower_1000_' .. self.floor_id .. '_B') then
		console_count = 2
	elseif game_string:IsThereString('tower_1000_' .. self.floor_id .. '_A') then
		console_count = 1
	else
		console_count = 0
	end

	self:set_console_count(console_count)

	message_system:Subscribe(self, typeof(CS.Oak.CustomStageEvent), 'on_event')
end

function local_class:on_event(e)
	local event_type = e:GetType()

	if event_type == typeof(CS.Oak.CustomStageEvent) then
		if e.Params ~= nil and e.Params.Length > 0 then
			if e.Params[0] == 'console_a' then
				-- A 콘솔 interact
				CS.UnityEngine.Debug.Log("A Console Interacted")
			elseif e.Params[0] == 'console_b' then
				-- B 콘솔 interact
				CS.UnityEngine.Debug.Log("B Console Interacted")
			elseif e.Params[0] == 'console_c' then
				-- C 콘솔 interact
				CS.UnityEngine.Debug.Log("C Console Interacted")
			elseif e.Params[0] == 'console_d' then
				-- D 콘솔 interact
				CS.UnityEngine.Debug.Log("D Console Interacted")
			elseif e.Params[0] == 'console_e' then
				-- E 콘솔 interact
				CS.UnityEngine.Debug.Log("E Console Interacted")
			elseif e.Params[0] == 'console_broken' then
				CS.UnityEngine.Debug.Log("Console_Broken Interacted")
			end
		end
	end

	return true
end

