function local_class:set_console_count(count)
	local a_console = get_field_object("A")
	local b_console = get_field_object("B")
	local c_console = get_field_object("C")
	local d_console = get_field_object("D")
	local e_console = get_field_object("E")
	local console_broken = get_field_object("console_broken") -- console_broken 기록물 없을때 중간 배치


	if count == 0 then
		console_broken.ActiveState = CS.Oak.ActiveState.Enabled
	else
		console_broken.ActiveState = CS.Oak.ActiveState.Disabled
	end

	if count > 0 then
		a_console.ActiveState = CS.Oak.ActiveState.Enabled
	else
		a_console.ActiveState = CS.Oak.ActiveState.Disabled
	end

	if count > 1 then
		b_console.ActiveState = CS.Oak.ActiveState.Enabled
	else
		b_console.ActiveState = CS.Oak.ActiveState.Disabled
	end

	if count > 2 then
		c_console.ActiveState = CS.Oak.ActiveState.Enabled
	else
		c_console.ActiveState = CS.Oak.ActiveState.Disabled
	end

	if count > 3 then
		d_console.ActiveState = CS.Oak.ActiveState.Enabled
	else
		d_console.ActiveState = CS.Oak.ActiveState.Disabled
	end

	if count > 4 then
		e_console.ActiveState = CS.Oak.ActiveState.Enabled
	else
		e_console.ActiveState = CS.Oak.ActiveState.Disabled
	end

	if count == 0 then
		console_broken.Position = field:GetMarker('console_position_0_A').position
	elseif count == 1 then
		a_console.Position = field:GetMarker('console_position_1_A').position
	elseif count == 2 then
		a_console.Position = field:GetMarker('console_position_2_A').position
		b_console.Position = field:GetMarker('console_position_2_B').position
	elseif count == 3 then
		a_console.Position = field:GetMarker('console_position_3_A').position
		b_console.Position = field:GetMarker('console_position_3_B').position
		c_console.Position = field:GetMarker('console_position_3_C').position
	elseif count == 4 then
		a_console.Position = field:GetMarker('console_position_4_A').position
		b_console.Position = field:GetMarker('console_position_4_B').position
		c_console.Position = field:GetMarker('console_position_4_C').position
		d_console.Position = field:GetMarker('console_position_4_D').position
		-- count == 5 일때는 기본 타일맵에 들어있는 위치와 같기때문에 따로 위치 이동을 하지 않는다.
	end
end

